steps.code:
const d = json(input) || {}, today = Date.parse(d.today) || Date.now(), day = 86400000;
const groups = { first: [], second: [], final: [] }, owed = {};
if (!Array.isArray(d.invoices)) return 'NOTHING OVERDUE: the brief has no list of invoices. Give {"invoices": [{"customer", "email", "number", "due", "amount", "currency"}]}.';
for (const i of d.invoices) {
  const due = Date.parse(i.due);
  if (Number.isNaN(due)) continue;
  const late = Math.floor((today - due) / day);
  if (late < 1) continue;
  (late <= 15 ? groups.first : late <= 45 ? groups.second : groups.final).push(i.customer + ' <' + (i.email || 'no email') + '>: invoice ' + i.number + ', ' + i.amount + ' ' + (i.currency || '') + ', ' + late + ' days late');
  owed[i.currency || '?'] = (owed[i.currency || '?'] || 0) + Number(i.amount || 0);
}
const part = (title, list) => list.length ? title + '\n- ' + list.join('\n- ') : '';
const text = [part('FIRST REMINDER (1 to 15 days late)', groups.first), part('SECOND REMINDER (16 to 45 days late)', groups.second), part('FINAL NOTICE (more than 45 days late)', groups.final)].filter(Boolean).join('\n\n');
return text ? text + '\n\nOwed in all: ' + Object.entries(owed).map(([c, v]) => v.toFixed(2) + ' ' + c).join(', ') : 'NOTHING OVERDUE';

steps.prompt:
These invoices are unpaid and late, grouped by how late they are:
{{step 1}}

If it says NOTHING OVERDUE, answer only: No reminders to send. Otherwise write one email for each customer, with its subject line. First reminder: friendly, assume it was missed. Second reminder: firm, ask for a payment date. Final notice: formal, say what happens next if it stays unpaid (we stop deliveries and pass it on for collection), without threats. Name the invoice, the amount and how late it is. At most 120 words each. Write in the language the customer's name or email suggests (Romanian for .ro), otherwise English.
